// Raumschiff gegen Felsbrocken: Seifenblasen zerplatzen Felsen, Felsen am Schiff kosten ein Leben.
const FELS_R = 16, SCHIFF_Y = 575, ZIEL_Y = SCHIFF_Y - FELS_R;

export default {
  title: "Raumschiff gegen Felsbrocken",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return { ship: { x: 140, y: SCHIFF_Y, w: 40, h: 30 }, bubbles: [], rocks: [], sparks: [], safe: 0, timer: 0, n: 0, kills: 0 };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 4, g.W - ship.w - 4);

    if (input.firePressed && s.bubbles.length < 3) {
      s.bubbles.push({ x: ship.x + 20, y: ship.y, r: 7 });
      g.sound("shoot");
    }
    for (const b of s.bubbles) b.y -= 6;
    s.bubbles = s.bubbles.filter((b) => b.y > g.TOP);

    if (s.safe > 0) s.safe -= 1;

    // Felsen erscheinen; jeder dritte zielt auf die Schiffsmitte (Flugzeit bis zum Schiff ~520 px)
    s.timer += 1;
    if (s.timer >= (g.level >= 2 ? 30 : 40)) {
      s.timer = 0;
      s.n += 1;
      const fall = 1.5 + 0.3 * g.level;
      const x = g.randInt(FELS_R, g.W - FELS_R);
      const r = { x, y: g.TOP - 10, r: FELS_R, vx: 0, vy: fall };
      if (s.n % 3 === 0) {
        const cx = ship.x + ship.w / 2;
        r.vx = g.clamp(((cx - x) * fall) / 520, -1.5, 1.5);
      }
      s.rocks.push(r);
    }
    for (const r of s.rocks) { r.x += r.vx; r.y += r.vy; }

    // Blase trifft Fels
    for (const b of s.bubbles) {
      for (const r of s.rocks) {
        if (b.gone || r.gone || g.dist(b, r) >= 22) continue;
        b.gone = true; r.gone = true;
        g.addScore(10);
        g.sound("pop");
        s.sparks.push({ x: r.x, y: r.y, t: 15 });
        s.kills += 1;
        if (s.kills % 10 === 0) { g.nextLevel(); g.sound("level"); }
      }
    }

    // Fels trifft Schiff
    if (s.safe === 0) {
      for (const r of s.rocks) {
        if (!r.gone && g.hit(r, ship)) {
          r.gone = true;
          g.sound("hurt");
          g.loseLife();
          s.safe = 60;
          break;
        }
      }
    }

    s.bubbles = s.bubbles.filter((b) => !b.gone);
    s.rocks = s.rocks.filter((r) => !r.gone && r.y < g.H + 20);
    for (const p of s.sparks) p.t -= 1;
    s.sparks = s.sparks.filter((p) => p.t > 0);
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.rocks) d.emoji("🪨", r.x, r.y, 32);
    for (const b of s.bubbles) d.emoji("🫧", b.x, b.y, 18);
    for (const p of s.sparks) d.circle(p.x, p.y, 2 + (15 - p.t) * 0.5, "yellow", { line: true });
    const sh = s.ship;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) d.emoji("🚀", sh.x + 20, sh.y + 15, 36);
  }
};

// Die Katze auf den Daechern: automatisch nach rechts laufen, mit fire springen, Fischgraeten sammeln.
const CAT = 28;
const GRAV = 0.5, JUMP = -9, LAUF = 1.5, ZIEL = 1000;

function makeRoofs() {
  return [
    { x0: 0, y: 520, w: 150 }, { x0: 190, y: 470, w: 120 }, { x0: 350, y: 520, w: 130 },
    { x0: 520, y: 440, w: 150 }, { x0: 710, y: 500, w: 140 }, { x0: 890, y: 430, w: 200 }
  ];
}

function supported(s, c) {
  return s.roofs.some((r) => r.y === c.y + CAT && c.x + CAT > r.x0 && c.x < r.x0 + r.w);
}

function respawn(s, c) {
  const nx = Math.max(0, c.x - 60);
  let r = s.roofs[0];
  for (const q of s.roofs) if (nx + CAT > q.x0 && nx < q.x0 + q.w) { r = q; break; }
  c.x = nx; c.y = r.y - CAT; c.vy = 0; c.ground = true;
}

export default {
  title: "Die Katze auf den Dächern",
  controls: ["fire"],
  lives: 3,

  init() {
    const roofs = makeRoofs();
    return {
      cat: { x: 20, y: 492, w: CAT, h: CAT, vy: 0, ground: true },
      roofs,
      fish: roofs.map((r) => ({ x: r.x0 + r.w / 2 - 10, y: r.y - 30, w: 20, h: 16 })),
      flag: { x: ZIEL, y: 370, w: 20, h: 60 },
      fische: 0,
      fertig: 0
    };
  },

  update(s, input, g) {
    if (s.fertig > 0) { s.fertig -= 1; if (s.fertig === 0) g.win(); return; }
    const c = s.cat;
    if (c.ground && input.firePressed) { c.vy = JUMP; c.ground = false; g.sound("jump"); }
    if (c.ground && !supported(s, c)) { c.ground = false; c.vy = 0; }
    if (!c.ground) c.vy = Math.min(c.vy + GRAV, 12);
    const oldBottom = c.y + CAT;
    c.y += c.vy;
    c.x += LAUF;
    if (!c.ground && c.vy >= 0) {
      for (const r of s.roofs) {
        if (c.x + CAT > r.x0 && c.x < r.x0 + r.w && oldBottom <= r.y && c.y + CAT >= r.y) {
          c.y = r.y - CAT; c.vy = 0; c.ground = true; break;
        }
      }
    }
    if (c.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s, c); return; }
    s.fish = s.fish.filter((f) => {
      if (g.hit(c, f)) { g.addScore(1); g.sound("coin"); s.fische += 1; return false; }
      return true;
    });
    if (g.hit(c, s.flag)) { s.fertig = 120; g.sound("level"); }
  },

  draw(s, d, g) {
    d.clear("cream");
    const cam = Math.max(0, s.cat.x - 100);
    for (const r of s.roofs) {
      const rx = r.x0 - cam;
      if (rx + r.w < -10 || rx > g.W + 10) continue;
      d.rect(rx, r.y, r.w, g.H - r.y, "yellow", { round: 8, line: true });
    }
    for (const f of s.fish) {
      if (f.x - cam < -20 || f.x - cam > g.W + 20) continue;
      d.emoji("🐟", f.x - cam + 10, f.y + 8, 22);
    }
    d.emoji("🚩", s.flag.x + 10 - cam, s.flag.y + 30, 34);
    d.emoji("🐱", s.cat.x - cam + CAT / 2, s.cat.y + CAT / 2, 30);
    if (s.fertig > 0) {
      d.text("Fischgräten: " + s.fische, g.W / 2, 260, { size: 28, align: "center" });
      d.text("Neustart mit fire", g.W / 2, 310, { size: 20, align: "center" });
    }
  }
};

// Memory mit gemalten Karten: 12 Karten, 6 Paare, Cursor mit Richtungen, Feuer waehlt. Neues Spiel ueber die Laufzeit.
const BILDER = ["🌞", "⛵", "🌸", "🐟", "⭐", "🍎"];
const SPALTEN = 4, ZELLE = 76, X0 = 28, Y0 = 120, KARTE = 68;
const ZUEGE = 30, WIEDERHOLEN = 12, ZEIGEN = 40, SIEG_FRAMES = 120;

export default {
  title: "Memory mit gemalten Karten",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const karten = [];
    for (const b of BILDER) { karten.push({ b, offen: false, paar: false }); karten.push({ b, offen: false, paar: false }); }
    for (let i = karten.length - 1; i > 0; i--) { const j = g.randInt(0, i); const t = karten[i]; karten[i] = karten[j]; karten[j] = t; }
    return { karten, cx: 0, cy: 0, halten: 0, wahl: [], zeigen: 0, zuege: 0, paare: 0, gewonnen: 0 };
  },

  update(s, input, g) {
    // Nach dem letzten Paar: Meldung zeigen, dann Spielende
    if (s.gewonnen > 0) { s.gewonnen -= 1; if (s.gewonnen === 0) g.win(); return; }
    // Zwei Karten ohne Paar kurz zeigen, dann wieder umdrehen
    if (s.zeigen > 0) {
      s.zeigen -= 1;
      if (s.zeigen === 0) { for (const i of s.wahl) s.karten[i].offen = false; s.wahl = []; }
      return;
    }
    // Cursor: sofort beim Druecken, dann alle WIEDERHOLEN Frames solange gehalten
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0), dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    if (dx !== 0 || dy !== 0) {
      if (s.halten % WIEDERHOLEN === 0) {
        s.cx = g.clamp(s.cx + dx, 0, SPALTEN - 1);
        s.cy = g.clamp(s.cy + dy, 0, Math.ceil(s.karten.length / SPALTEN) - 1);
      }
      s.halten += 1;
    } else s.halten = 0;
    if (!input.firePressed) return;
    const i = s.cy * SPALTEN + s.cx;
    if (i >= s.karten.length) return;
    const k = s.karten[i];
    if (k.offen || k.paar) return;
    k.offen = true; s.wahl.push(i); g.sound("pop");
    if (s.wahl.length < 2) return;
    s.zuege += 1;
    const a = s.karten[s.wahl[0]], b = s.karten[s.wahl[1]];
    if (a.b === b.b) {
      a.paar = true; b.paar = true; s.wahl = []; s.paare += 1;
      g.addScore(10); g.sound("coin");
      if (s.paare === BILDER.length) {
        g.addScore(Math.max(0, ZUEGE - s.zuege));
        s.gewonnen = SIEG_FRAMES; g.sound("win");
        return;
      }
    } else {
      g.addScore(1);
      s.zeigen = ZEIGEN;
    }
    if (s.zuege >= ZUEGE) g.gameOver();
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Züge: " + s.zuege + " / " + ZUEGE, g.W / 2, 80, { size: 20, align: "center" });
    for (let i = 0; i < s.karten.length; i++) {
      const k = s.karten[i];
      const x = X0 + (i % SPALTEN) * ZELLE, y = Y0 + Math.floor(i / SPALTEN) * ZELLE;
      if (k.offen || k.paar) {
        d.rect(x, y, KARTE, KARTE, "cream", { round: 10, line: true });
        d.emoji(k.b, x + KARTE / 2, y + KARTE / 2, 40);
      } else {
        d.rect(x, y, KARTE, KARTE, "yellow", { round: 10, shadow: true, line: true });
        d.emoji("❔", x + KARTE / 2, y + KARTE / 2, 34);
      }
    }
    const cx = X0 + s.cx * ZELLE - 4, cy = Y0 + s.cy * ZELLE - 4;
    d.rect(cx, cy, KARTE + 8, 4, "red"); d.rect(cx, cy + KARTE + 4, KARTE + 8, 4, "red");
    d.rect(cx, cy, 4, KARTE + 8, "red"); d.rect(cx + KARTE + 4, cy, 4, KARTE + 8, "red");
    if (s.gewonnen > 0) {
      d.text("Geschafft in " + s.zuege + " Versuchen!", g.W / 2, 340, { size: 24, color: "ink", align: "center" });
    }
  }
};

// Gummibärchen-Schätzspiel: drei Runden, im Glas liegt eine zufällige Anzahl Bärchen (🍬). Punkte je Schätzung.
export default {
  title: "Gummibärchen-Schätzspiel",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { runde: 1, n: g.randInt(10, 60), schaetz: 30, phase: "schaetzen", zeigen: 0, halten: 0, punkte: [], gesamt: 0 };
  },

  update(s, input, g) {
    if (s.phase === "ende") return;

    if (s.phase === "zeigen") {
      s.zeigen -= 1;
      if (s.zeigen <= 0) {
        if (s.runde >= 3) {
          s.phase = "ende";
          if (s.gesamt >= 100) g.win(); else g.gameOver();
          return;
        }
        s.runde += 1;
        s.n = g.randInt(10, 60);
        s.schaetz = 30;
        s.halten = 0;
        s.phase = "schaetzen";
        g.sound("level");
      }
      return;
    }

    // schaetzen: sofort beim Druecken, beim Halten alle 10 Frames
    const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    if (dir !== 0) {
      if (s.halten % 10 === 0) s.schaetz = g.clamp(s.schaetz + dir, 0, 100);
      s.halten += 1;
    } else s.halten = 0;

    if (input.firePressed) {
      const p = Math.max(0, 50 - Math.abs(s.schaetz - s.n));
      s.punkte.push(p);
      s.gesamt += p;
      if (p > 0) g.addScore(p);
      g.sound("coin");
      s.phase = "zeigen";
      s.zeigen = 120;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Runde " + s.runde + " von 3", g.W / 2, 70, { size: 22, align: "center" });

    if (s.phase === "ende") {
      const sieg = s.gesamt >= 100;
      d.text(sieg ? "Gesamtsieger: du" : "Spiel vorbei", g.W / 2, 200, { size: 26, align: "center" });
      d.text("Gesamt: " + s.gesamt + " Punkte", g.W / 2, 250, { size: 24, align: "center" });
      for (let i = 0; i < s.punkte.length; i++) {
        d.text("Runde " + (i + 1) + ": " + s.punkte[i] + " Punkte", g.W / 2, 310 + i * 40, { size: 20, align: "center" });
      }
      return;
    }

    d.rect(60, 150, 240, 280, "cream", { round: 16, line: true });
    for (let i = 0; i < s.n; i++) {
      const col = i % 8, row = Math.floor(i / 8);
      d.emoji("🍬", 90 + col * 24, 180 + row * 30, 22);
    }

    if (s.phase === "zeigen") {
      d.text("Richtig: " + s.n, g.W / 2, 470, { size: 28, align: "center" });
      d.text("Deine Schätzung: " + s.schaetz, g.W / 2, 515, { size: 20, align: "center" });
      d.text("Abweichung: " + Math.abs(s.schaetz - s.n), g.W / 2, 550, { size: 20, align: "center" });
    } else {
      d.text("Schätzung: " + s.schaetz, g.W / 2, 470, { size: 28, align: "center" });
      d.text("Links/Rechts ändern, Feuer bestätigt", g.W / 2, 515, { size: 16, align: "center" });
    }
  }
};

// Wuerfelrennen: vier Spieler am selben Geraet wuerfeln abwechselnd, wer zuerst 100 Punkte hat, gewinnt.
const ZIEL = 100, ZUGLIMIT = 30;

export default {
  title: "Würfelrennen bis 100 Punkte",
  controls: ["fire"],
  lives: 1,

  init(g) {
    const s = {};
    neu(s);
    return s;
  },

  update(s, input, g) {
    if (s.ende) {
      if (input.firePressed) neu(s);
      return;
    }
    if (s.zeigen > 0) s.zeigen -= 1;
    if (!input.firePressed) return;

    s.wurf = g.randInt(1, 6);
    s.punkte[s.am] += s.wurf;
    g.addScore(s.wurf);
    s.zuege += 1;
    s.zeigen = 60;

    if (s.punkte[s.am] >= ZIEL) {
      s.ende = true;
      s.sieger = s.am;
      g.sound("win");
    } else if (s.zuege >= ZUGLIMIT) {
      g.gameOver();
    } else {
      s.am = (s.am + 1) % 4;
      g.sound("jump");
    }
  },

  draw(s, d) {
    d.clear("cream");
    for (let i = 0; i < 4; i++) {
      const y = 60 + i * 70;
      if (i === s.am && !s.ende) d.rect(16, y - 4, 328, 64, "red", { round: 12 });
      d.rect(20, y, 320, 56, "yellow", { round: 10 });
      d.text(s.namen[i] + ": " + s.punkte[i] + " Punkte", 36, y + 34, { size: 22, color: "ink" });
    }
    if (s.ende) {
      d.text("Gewinner: " + s.namen[s.sieger], 180, 330, { size: 32, color: "ink", align: "center" });
      d.rect(90, 380, 180, 56, "red", { round: 12, shadow: true });
      d.text("Neues Spiel", 180, 416, { size: 22, color: "cream", align: "center" });
      d.text("Tippen fuer neues Spiel", 180, 480, { size: 18, color: "ink", align: "center" });
      return;
    }
    d.emoji("🎲", 180, 330, 120);
    if (s.zeigen > 0) d.text(String(s.wurf), 180, 420, { size: 48, color: "ink", align: "center" });
    d.text("Tippen zum Würfeln", 180, 520, { size: 18, color: "ink", align: "center" });
  }
};

function neu(s) {
  s.namen = ["Spieler 1", "Spieler 2", "Spieler 3", "Spieler 4"];
  s.punkte = [0, 0, 0, 0];
  s.am = 0;
  s.wurf = 0;
  s.zeigen = 0;
  s.zuege = 0;
  s.ende = false;
  s.sieger = -1;
}

// Kartenspiel gegen den Computer (Mau-Mau-artig): 4 Spieler im Uhrzeigersinn, Farbe oder Zahl passend ablegen.
const FARBEN = ["🍎", "🌟", "🐸", "⛵"];
const STUFEN = ["leicht", "mittel", "schwer"];
const WARTE = [60, 40, 20];
const ZUGLIMIT = 30;

export default {
  title: "Kartenspiel gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const stapel = [];
    for (let c = 0; c < 4; c++) for (let n = 1; n <= 7; n++) stapel.push({ c, n });
    mischen(stapel, g);
    const hands = [[], [], [], []];
    for (let k = 0; k < 5; k++) for (let p = 0; p < 4; p++) hands[p].push(stapel.pop());
    const ablage = [stapel.pop()];
    return { phase: "wahl", stufe: 1, stapel, ablage, hands, zug: 0, zuege: 0, cx: 0, cb: false, halten: 0, pause: 0, ende: 0, gewinner: -1 };
  },

  update(s, input, g) {
    if (s.phase === "wahl") { wahl(s, input, g); return; }
    if (s.phase === "ende") {
      s.ende -= 1;
      if (s.ende <= 0) { if (s.gewinner === 0) g.win(); else g.gameOver(); }
      return;
    }
    if (s.zug === 0) spielerZug(s, input, g);
    else if (s.pause > 0) s.pause -= 1;
    else computerZug(s, g);
  },

  draw(s, d, g) {
    d.clear("yellow");
    if (s.phase === "wahl") {
      d.text("Kartenspiel gegen den Computer", 180, 150, { size: 18, align: "center" });
      d.text("Stufe: " + STUFEN[s.stufe], 180, 220, { size: 32, align: "center" });
      d.text("leicht / mittel / schwer", 180, 270, { size: 18, align: "center" });
      d.text("Links/rechts wählen, Feuer startet", 180, 320, { size: 14, align: "center" });
      return;
    }
    d.text("Züge: " + s.zuege + " / " + ZUGLIMIT, 180, 70, { size: 18, align: "center" });
    for (let i = 0; i < 4; i++) {
      const x = 45 + i * 90;
      d.emoji(i === 0 ? "🙂" : "🤖", x, 105, 26);
      d.text(String(s.hands[i].length), x, 140, { size: 18, align: "center" });
    }
    const top = s.ablage[s.ablage.length - 1];
    drawCard(d, 60, 170, top);
    d.rect(250, 170, 44, 60, "ink", { round: 6, line: true });
    d.text("?", 272, 190, { size: 22, color: "cream", align: "center" });
    d.text(String(s.stapel.length), 272, 240, { size: 14, align: "center" });
    d.rect(40, 250, 280, 44, "cream", { round: 12, shadow: true, line: true });
    d.text("Karte ziehen", 180, 262, { size: 20, color: "ink", align: "center" });
    if (s.phase === "spiel" && s.cb) frame(d, 40, 250, 280, 44);
    if (s.phase === "ende") {
      d.text("Gewinner: " + (s.gewinner === 0 ? "Du" : "Computer " + s.gewinner), 180, 320, { size: 26, color: "red", align: "center" });
    } else {
      d.text(s.zug === 0 ? "Du bist dran" : "Computer " + s.zug + " spielt", 180, 320, { size: 18, align: "center" });
    }
    d.text("Deine Hand", 180, 440, { size: 14, align: "center" });
    const hand = s.hands[0], n = hand.length;
    const total = n > 0 ? (n - 1) * 50 + 44 : 0;
    const off = Math.max(0, Math.min(s.cx * 50 - 120, total - 320));
    for (let i = 0; i < n; i++) {
      const x = 20 + i * 50 - off, y = 470;
      drawCard(d, x, y, hand[i]);
      if (i === s.cx && !s.cb && s.phase === "spiel") frame(d, x, y, 44, 60);
    }
  }
};

function wahl(s, input, g) {
  const dir = (input.right || input.down ? 1 : 0) - (input.left || input.up ? 1 : 0);
  if (dir !== 0) {
    if (s.halten % 12 === 0) s.stufe = g.clamp(s.stufe + dir, 0, 2);
    s.halten += 1;
  } else s.halten = 0;
  if (input.firePressed) { s.phase = "spiel"; s.zug = 0; s.pause = 0; s.halten = 0; }
}

function spielerZug(s, input, g) {
  const hand = s.hands[0];
  if (input.up) s.cb = true;
  if (input.down) s.cb = false;
  const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  if (dx !== 0) {
    if (s.halten % 12 === 0) s.cx = g.clamp(s.cx + dx, 0, Math.max(0, hand.length - 1));
    s.halten += 1;
  } else s.halten = 0;
  s.cx = Math.min(s.cx, Math.max(0, hand.length - 1));
  if (!input.firePressed) return;
  if (s.cb) {
    const card = ziehen(s, g);
    if (card) { hand.push(card); g.addScore(1); g.sound("jump"); }
    finishTurn(s, g, 0);
    return;
  }
  const card = hand[s.cx];
  if (!card || !passt(card, s.ablage[s.ablage.length - 1])) return;
  hand.splice(s.cx, 1);
  s.ablage.push(card);
  g.addScore(5);
  g.sound("pop");
  finishTurn(s, g, 0);
}

function computerZug(s, g) {
  const i = s.zug, hand = s.hands[i], top = s.ablage[s.ablage.length - 1];
  let idx = -1;
  for (let j = 0; j < hand.length; j++) {
    if (!passt(hand[j], top)) continue;
    if (idx < 0 || (s.stufe === 2 && hand[j].n > hand[idx].n)) idx = j;
  }
  if (idx >= 0) {
    const card = hand.splice(idx, 1)[0];
    s.ablage.push(card);
    g.sound("pop");
  } else {
    const card = ziehen(s, g);
    if (card) hand.push(card);
  }
  finishTurn(s, g, i);
}

function finishTurn(s, g, who) {
  s.zuege += 1;
  if (s.hands[who].length === 0) { endRunde(s, g, who); return; }
  if (s.zuege >= ZUGLIMIT) {
    const best = besterComputer(s);
    if (s.hands[0].length < s.hands[best].length) endRunde(s, g, 0);
    else endRunde(s, g, best);
    return;
  }
  s.zug = (s.zug + 1) % 4;
  s.pause = s.zug === 0 ? 0 : WARTE[s.stufe];
  s.halten = 0;
}

function endRunde(s, g, w) {
  s.phase = "ende";
  s.gewinner = w;
  s.ende = 90;
  if (w === 0) { g.addScore(20); g.sound("win"); } else g.sound("lose");
}

function besterComputer(s) {
  let b = 1;
  for (let i = 2; i <= 3; i++) if (s.hands[i].length < s.hands[b].length) b = i;
  return b;
}

function ziehen(s, g) {
  if (s.stapel.length === 0) {
    if (s.ablage.length <= 1) return null;
    const top = s.ablage.pop();
    s.stapel = s.ablage;
    s.ablage = [top];
    mischen(s.stapel, g);
  }
  return s.stapel.pop();
}

function passt(a, b) {
  return a.c === b.c || a.n === b.n;
}

function mischen(liste, g) {
  for (let i = liste.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = liste[i]; liste[i] = liste[j]; liste[j] = t;
  }
}

function drawCard(d, x, y, c) {
  d.rect(x, y, 44, 60, "cream", { round: 6, line: true });
  d.emoji(FARBEN[c.c], x + 22, y + 20, 22);
  d.text(String(c.n), x + 22, y + 44, { size: 18, color: "ink", align: "center" });
}

function frame(d, x, y, w, h) {
  d.rect(x - 4, y - 4, w + 8, 4, "red");
  d.rect(x - 4, y + h, w + 8, 4, "red");
  d.rect(x - 4, y, 4, h, "red");
  d.rect(x + w, y, 4, h, "red");
}

// Segelboot gegen schwebende Ballons: Wasserbomben nach oben, Ballons fallen herab, Wasserrand kostet Leben.
export default {
  title: "Segelboot gegen schwebende Ballons",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return { ship: { x: 160, y: 580, w: 40, h: 30 }, bombs: [], balloons: [], splash: [], cool: 0, hits: 0 };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 0, 320);

    if (s.cool > 0) s.cool -= 1;
    if (input.firePressed && s.cool === 0 && s.bombs.length < 3) {
      s.bombs.push({ x: ship.x + 20, y: ship.y, r: 6, used: false });
      s.cool = 12;
      g.sound("shoot");
    }
    for (const b of s.bombs) b.y -= 8;
    s.bombs = s.bombs.filter((b) => b.y >= g.TOP && !b.used);

    if (g.frame % Math.max(20, 60 - 5 * g.level) === 0) {
      s.balloons.push({ x: g.randInt(20, 340), y: 60, r: 18, pop: false });
    }
    const speed = 0.6 + 0.1 * g.level;
    for (const bal of s.balloons) bal.y += speed;

    for (const bomb of s.bombs) {
      for (const bal of s.balloons) {
        if (bal.pop || bomb.used) continue;
        if (g.dist(bomb, bal) < 22) {
          bal.pop = true;
          bomb.used = true;
          s.hits += 1;
          g.addScore(10 * g.level);
          g.sound("pop");
          s.splash.push({ x: bal.x, y: bal.y, t: 20 });
          if (s.hits % 10 === 0) { g.nextLevel(); g.sound("level"); }
        }
      }
    }
    s.bombs = s.bombs.filter((b) => !b.used);

    const keep = [];
    for (const bal of s.balloons) {
      if (bal.pop) continue;
      if (bal.y >= 560) { g.sound("hurt"); g.loseLife(); continue; }
      keep.push(bal);
    }
    s.balloons = keep;

    for (const p of s.splash) p.t -= 1;
    s.splash = s.splash.filter((p) => p.t > 0);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(0, 560, g.W, g.H - 560, "yellow");
    for (const bal of s.balloons) d.emoji("🎈", bal.x, bal.y, 36);
    for (const bomb of s.bombs) d.emoji("💧", bomb.x, bomb.y, 20);
    for (const p of s.splash) d.emoji("💦", p.x, p.y, 30);
    d.emoji("⛵", s.ship.x + 20, s.ship.y + 15, 36);
  }
};
